#include <iostream>
using namespace std;

int main() {
    int a[4] = {10, 20, 30, 40};
    int *p = a;
    cout << (p == &a[0]) << endl;
    cout << a[2] << " " << *(a + 2) << endl;
    cout << *a << " " << *(p + 3) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[5] = {2, 4, 6, 8, 10};
    int *p = a;
    int sum = 0;
    for (int i = 0; i < 5; i++) {
        sum += *p;
        p++;
    }
    cout << "Sum = " << sum << endl;
    cout << "p moved " << (p - a) << " places" << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int a[5] = {1, 2, 3, 4, 5};
    int *p = a + 1;
    cout << "Bytes in a: " << sizeof(a) << endl;
    cout << "Elements in a: " << sizeof(a) / sizeof(a[0]) << endl;
    cout << "Same size as p? " << (sizeof(p) == sizeof(a)) << endl;
    cout << *p << " " << p[2] << " " << *(p + 3) << " " << p[-1] << endl;
    return 0;
}

